documentations-slot--slot.snippet:
import { Component } from '@angular/core';
import { GallerySlot } from 'ng-gallery';
import { GalleryModule } from 'ng-gallery';

@Component({
  selector: 'app-demo',
  imports: [GallerySlot, GalleryModule],
  template: `
    <gallery class="gallery-example" [items]="items" gap="32">
        <div *galleryItemDef="let item; index as i" class="slide">
            <span>{{ i + 1 }}</span>
        </div>
        <div
            class="static-panel"
            [gallerySlot]="position"
            [gallerySlotAlign]="align"
            [gallerySlotJustify]="justify">
            Static Content
        </div>
    </gallery>`,
})
export class DemoComponent {
  position = 'center';
  align = 'center';
  justify = 'center';
}
